CREATE TABLE IF NOT EXISTS project_files(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), object_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL CHECK(length(filename) BETWEEN 1 AND 180), size_bytes INTEGER NOT NULL CHECK(size_bytes BETWEEN 1 AND 10485760), uploaded_by TEXT NOT NULL CHECK(uploaded_by IN ('admin','customer')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS project_files_project ON project_files(project_id,created_at,id);
CREATE TRIGGER IF NOT EXISTS project_file_guard BEFORE INSERT ON project_files WHEN NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.project_id AND status IN ('active','paused')) OR (SELECT COUNT(*) FROM project_files WHERE project_id=NEW.project_id)>=200 BEGIN SELECT RAISE(ABORT,'Project file limit or status'); END;
